  const state = { role: "expert", expertSection: "overview", customerSection: "summary", adminSection: "catalog", scenario: "normal", routeView: "planned", allocationView: "cargo", selectedCargo: "B1", selectedUnit: "TR-24", documentContext: "all", selectedDelivery: "A1", catalogFilter: "all", catalogSearch: "", hs: "", receipt: false, followupDone: false, latestFollowup: "شرکت حمل زمان ارسال سند را تأیید کرد.", location: "نزدیک آلماتی", locationTime: "۱۴:۳۰", locationSource: "گزارش شرکت حمل", customerMessage: "یک موضوع مربوط به مدارک حمل در حال پیگیری است. در حال حاضر تغییری در زمان تقریبی رسیدن ایجاد نکرده است.", reference: [4,6,1,2], referenceDate: "۱ شهریور", referenceHistory: [], decision: null, exceptionRequested: false, allocationHistory: ["۴۰ کارتن قطعات موتور از کامیون TR-12 به کامیون TR-18 منتقل شد؛ پایانه خورگوس، دیروز ۱۶:۴۰."], updates: [], catalogActive: {truck:true,rail:true,reeferWagon:false,container40:true} };
